
import type { DeliveryProfileOriginPolicyInput } from './DeliveryProfileOriginPolicyInput.js';
import type { DimensionsInput } from './DimensionsInput.js';
import type { WeightInput } from './WeightInput.js';

export type DeliveryProfileConfigurationInput = { /** Required as a non-empty unique list when requirement is required. quote accepts shipment, pickup, and local_delivery. manual accepts digital and service. */ "allowed_types"?: Array<"shipment" | "pickup" | "local_delivery" | "digital" | "service">; /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls which delivery obligations can share a choice group. */ "combination_policy"?: "combine_when_compatible" | "separate_profile" | "separate_line_item" | "fulfill_alone"; /** Optional physical dimensions used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "dimensions"?: DimensionsInput; /** Required for quote resolution and forbidden for none or manual resolution. fixed_location requires location_id. inventory_routing forbids location_id and applies only to tracked inventory. method_origin forbids location_id. */ "origin_policy"?: DeliveryProfileOriginPolicyInput; /** Whether delivery planning applies. none forbids every other configuration field. required also requires resolution_mode and allowed_types, plus the fields required by that resolution mode. */ "requirement": "none" | "required"; /** Required when requirement is required. quote plans physical delivery and requires origin_policy, combination_policy, and splitting_policy. manual supports digital and service items and forbids physical planning fields. */ "resolution_mode"?: "quote" | "manual"; /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls whether a line item quantity can be split across delivery assignments. */ "splitting_policy"?: "whole_line_item" | "quantity_split_allowed"; /** Optional physical weight used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "weight"?: WeightInput; };
